package com.agriconnect.order;import java.math.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component class CropInventoryClient{private final RestClient c;private final String key;CropInventoryClient(RestClient.Builder b,@Value("${crop-service.url}")String u,@Value("${internal.api-key}")String k){c=b.baseUrl(u).build();key=k;}Map<String,Object>batch(long id){return get("/internal/crop-batches/"+id);}Map<String,Object>reserve(UUID request,String ref,long batch,long buyer,BigDecimal q,Instant expires){return post("/internal/inventory/reservations",Map.of("requestId",request,"orderReference",ref,"cropBatchId",batch,"buyerId",buyer,"quantity",q,"expiresAt",expires));}Map<String,Object>commit(UUID id){return post("/internal/inventory/reservations/"+id+"/commit",Map.of());}Map<String,Object>release(UUID id){return post("/internal/inventory/reservations/"+id+"/release",Map.of());}private Map<String,Object>get(String u){try{return c.get().uri(u).header("X-Internal-Api-Key",key).retrieve().body(Map.class);}catch(RestClientException e){throw new DomainException(HttpStatus.SERVICE_UNAVAILABLE,"DOWNSTREAM_SERVICE_UNAVAILABLE","Crop service is unavailable");}}private Map<String,Object>post(String u,Object body){try{return c.post().uri(u).header("X-Internal-Api-Key",key).body(body).retrieve().body(Map.class);}catch(HttpClientErrorException.Conflict e){throw new DomainException(HttpStatus.CONFLICT,"INSUFFICIENT_INVENTORY","The requested quantity is no longer available");}catch(RestClientException e){throw new DomainException(HttpStatus.SERVICE_UNAVAILABLE,"DOWNSTREAM_SERVICE_UNAVAILABLE","Crop service is unavailable");}}}
